import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易尚氏学 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易尚氏学 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/shangshi/021.md","filePath":"zh/classics/shangshi/021.md"}'),s={name:"zh/classics/shangshi/021.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>雷出地上。得众志行。故豫。豫。和乐也。归藏作分。言震雷上出。与地分离也。又一阳界于五阴之间。使上下分别。与周易义异。震为君。故曰建侯。与屯同义。坤为师。顺以动。故利行师。</p><p>彖曰。豫。刚应而志行。顺以动豫。豫顺以动。故天地如之。而况建侯行师乎。天地以顺动。故日月不过。而四时不忒。圣人以顺动。则刑罚清而民服。豫之时义大矣哉。</p><p>艮为天。坤为地。艮为日。坎为月。顺故不过不忒。坎为刑罚。坤为民。坤顺故刑罚清而民服。艮为时。震卦数四。故曰四时。坎为圣。(虞氏逸象)李鼎祚以震为圣。非。</p><p>象曰。雷出地奋。豫。先王以作乐崇德。殷荐之上帝。以配祖考。</p><p>震为乐。为仁德。为帝。为荐。荐进也。殷盛也。艮为祖考。(象失传。只易林知之。实小过六二过其祖。即以艮为祖。详焦氏易诂。)古帝王作乐。皆以象其功德。用以郊天。使祖考配享。雷出地奋。声容象之。故先王取以为法。震为王。</p><p>初六。呜豫。凶。</p><p>初应四。四震为鸣。故曰鸣豫。爻在此而象在应。如蒙三之金夫。泰二之包巟凭河。及此为易之通例。自此例不明。于是明夷初九之飞及翼。皆以离为象矣。初六得敌。不能应四。故凶。</p><h3 id="象曰。初六鸣豫。志穷凶也。" tabindex="-1">象曰。初六鸣豫。志穷凶也。 <a class="header-anchor" href="#象曰。初六鸣豫。志穷凶也。" aria-label="Permalink to “象曰。初六鸣豫。志穷凶也。”">​</a></h3><p>穷者极也。初为二三所隔。应四难。故曰志穷。</p><p>六二。介于石。不终日。贞吉。</p><p>释文云。介古文作硋。郑古八反。云磨硋也。马作抯。云触小石声。案说文。抯刮也。古黠切。广韵揩抯物也。音戛。揩抯即磨硋。皆触坚不相入之声。又庄子马蹄篇。加之以衡扼。齐之以月题。而马知介倪。陆云介徐古八反。亦音戛。介者触。倪睨同。介倪者。即马因感触月题等物之磨硋。因而睥睨也。是庄子亦以介为触。然则硋抯介音义并同。盖非触坚。不能有磨戛之声。然则介于石即触于石。艮为石。二前遇之。故触于石。易之道。异性为类。同性相敌。二五无应。承乘皆阴。如触于石之不相入。触石不入。故君子见几而作。不俟终日也。旧解诂硋字是。而义则不详。须知硋于石。乃危辞。以形容二之失类。故系云介如石焉。宁用终日。断可识矣。艮为终日。易林大过之艮云。终日至暮。不离其乡。以艮为终日。坎为暮也。夫居中位。而又能危惕自警。故贞吉也。宋翔凤以说文无硋字。有抯。便谓硋为讹字。岂知晋孔坦答刘聪求降书曰。何知几之先觉。硋石之易悟。桓温传。亦曰硋如石所以成务。不止郑作硋也。</p><h3 id="象曰。不终日。贞吉。以中正也。" tabindex="-1">象曰。不终日。贞吉。以中正也。 <a class="header-anchor" href="#象曰。不终日。贞吉。以中正也。" aria-label="Permalink to “象曰。不终日。贞吉。以中正也。”">​</a></h3><p>二当位。故中正。</p><p>六三。盱豫。悔。迟有悔。</p><p>说文。盱。张目也。尔雅。盱忧也。又诗小雅。云何盱矣。郑笺病也。艮为视。(象失传。祇易及易林用之。详焦氏易诂)。坤为病。故曰盱。诸爻独三得承阳。然失位。故睢盱上视。有忧悔也。艮止故迟。有又通。迟有悔者。言迟疑不决。又有悔也。盱豫句。悔一字句。</p><h3 id="象曰。盱豫有悔。位不当也。" tabindex="-1">象曰。盱豫有悔。位不当也。 <a class="header-anchor" href="#象曰。盱豫有悔。位不当也。" aria-label="Permalink to “象曰。盱豫有悔。位不当也。”">​</a></h3><p>位不当。释盱豫之故。</p><p>九四。由豫。大有得。勿疑。朋盍簪。</p><p>盂子。由由然与之偕。注。由由。自得之貌。由豫者。从容和乐也。坎为疑。上下四阴附之。阳遇阴则通。故曰大有得勿疑。阳以阴为朋。盍合也。簪与笄同。所以括发。朋盍簪言群阴归四。有若簪之括发也。臧庸云。象盍簪者。取一阳横贯于五阴之中。可谓观象独深。又杜诗。盍簪喧枥马。言群马絷于一杠之上。故以盍簪为喻。此语解易。可谓明白如昼矣。艮为簪。易林。恒之咸云。簪短带长。以咸艮为簪。复之节语同。亦以节之互艮为簪。凡易林象。无不本于易。子夏传为韩婴作。在汉易为最古。即作簪。故焦氏亦读为簪。与子夏传同。至东汉则多改字，其详皆在焦氏易诂中。(后之人于笄簪括发之形象。茫昧失考。故于易象维妙维肖之朋盍簪三字。皆不知其故。而尤以谓汉以前无簪名者为失考。仪礼簪衣于裳。韩非子周主亡玉簪。李斯谏逐客。宛珠之簪。谓汉以前无者非也。)</p><h3 id="象曰。由豫大有得。志大行也。" tabindex="-1">象曰。由豫大有得。志大行也。 <a class="header-anchor" href="#象曰。由豫大有得。志大行也。" aria-label="Permalink to “象曰。由豫大有得。志大行也。”">​</a></h3><p>志谓坎。上下五阴皆孚于四。故曰志大行。</p><p>六五。贞疾。恒不死。</p><p>坎为疾。震生故曰不死。五以阴柔处尊位。乘刚势逆。故常疾。然久而不死。以处中位也。如齐田得民。姜亦不遽亡也。</p><h3 id="象曰。六五贞疾。乘刚也。" tabindex="-1">象曰。六五贞疾。乘刚也。 <a class="header-anchor" href="#象曰。六五贞疾。乘刚也。" aria-label="Permalink to “象曰。六五贞疾。乘刚也。”">​</a></h3><p>恒不死。中未亡也。中未亡之故。以得中故也。</p><p>上六。冥豫。成有渝。无咎。</p><p>冥昧不事事。功之成者。必渐隳矣。故曰成有渝。然当位。目前虽无大咎。久则祸至。故象曰何可长。</p><h3 id="象曰。冥豫在上。何可长也。" tabindex="-1">象曰。冥豫在上。何可长也。 <a class="header-anchor" href="#象曰。冥豫在上。何可长也。" aria-label="Permalink to “象曰。冥豫在上。何可长也。”">​</a></h3><p>何可长。言不足恃。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
